// ============================================================================
// LOOKUP FUNCTIONS
// ============================================================================

/**
 * Look up festivals by matching criteria, replicating the Python
 * get_festival() logic from vratha.py.
 *
 * Each non-null criterion must match the festival entry.
 * For tithi, an array of possible tithis can be provided (matching any).
 */
export function lookupFestivals(criteria: {
  tithi?: number | number[];
  nakshatra?: number | number[];
  tamilMonth?: number;
  tamilDay?: number;
  vaara?: number;
  adhikMaasa?: number | null;
  calendarType?: number;
}): FestivalEntry[] {
  return FESTIVAL_DATA.filter((row) => {
    if (criteria.calendarType !== undefined && row.calendarType !== criteria.calendarType) {
      return false;
    }
    // For each criterion field, if the criterion is provided and the row has a value,
    // they must match. If the row has null for that field, it is not filtered out.
    if (criteria.tithi !== undefined && row.tithi !== null) {
      const tithis = Array.isArray(criteria.tithi) ? criteria.tithi : [criteria.tithi];
      if (!tithis.includes(row.tithi)) return false;
    }
    if (criteria.nakshatra !== undefined && row.nakshatra !== null) {
      const naks = Array.isArray(criteria.nakshatra) ? criteria.nakshatra : [criteria.nakshatra];
      if (!naks.includes(row.nakshatra)) return false;
    }
    if (criteria.tamilMonth !== undefined && row.tamilMonth !== null) {
      if (row.tamilMonth !== criteria.tamilMonth) return false;
    }
    if (criteria.tamilDay !== undefined && row.tamilDay !== null) {
      if (row.tamilDay !== criteria.tamilDay) return false;
    }
    if (criteria.vaara !== undefined && row.vaara !== null) {
      if (row.vaara !== criteria.vaara) return false;
    }
    if (criteria.adhikMaasa !== undefined && row.adhikMaasa !== null) {
      if (row.adhikMaasa !== criteria.adhikMaasa) return false;
    }
    return true;
  });
}

/**
 * Search festivals by name (case-insensitive substring match).
 * Searches the English name by default, or a specified language.
 */
export function searchFestivals(
  query: string,
  language: FestivalLanguage = "en"
): FestivalEntry[] {
  const q = query.toLowerCase();
  return FESTIVAL_DATA.filter((row) => row[language].toLowerCase().includes(q));
}

/**
 * Get the festival name in a given language.
 */
export function getFestivalName(
  entry: FestivalEntry,
  language: FestivalLanguage = "en"
): string {
  return entry[language];
}

